using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class F1WildInventory {
 static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");static string Out=>Root+"/Docs/Review/2026-11-13_1F_WildernessDetail/";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");Directory.CreateDirectory(Out);string temp=Path.Combine(Path.GetTempPath(),"AfterSeconds_WildernessDetail_20261113");Directory.CreateDirectory(temp+"/before");File.Copy(s.path,temp+"/before/Level_1F_Factory.unity",false);var root=GameObject.Find("WildernessEnding").transform;var terrain=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Terrain>(true)).ToArray();var details=root.Find("DryScrubAndStone").Cast<Transform>().Select(t=>new{t.name,path=AnimationUtility.CalculateTransformPath(t,null),position=V(t.position),scale=V(t.localScale),rotation=V(t.eulerAngles),meshes=t.GetComponentsInChildren<MeshFilter>().Select(f=>new{path=AnimationUtility.CalculateTransformPath(f.transform,t),mesh=f.sharedMesh.name,asset=AssetDatabase.GetAssetPath(f.sharedMesh),boundsMin=V(f.sharedMesh.bounds.min),boundsMax=V(f.sharedMesh.bounds.max),vertices=f.sharedMesh.vertexCount,materials=f.GetComponent<Renderer>().sharedMaterials.Select(m=>AssetDatabase.GetAssetPath(m)).ToArray(),colliders=f.GetComponents<Collider>().Select(c=>c.GetType().Name).ToArray()}).ToArray()}).ToArray();
 foreach(var t in terrain){string p=AssetDatabase.GetAssetPath(t.terrainData);File.Copy(p,temp+"/before/"+Path.GetFileName(p),false);var data=t.terrainData;var heights=data.GetHeights(0,0,data.heightmapResolution,data.heightmapResolution);using(var writer=new BinaryWriter(File.Open(temp+"/"+t.name+".raw",FileMode.Create)))foreach(float h in heights)writer.Write(h);}
 string[] protect={"FS_SunsetSky.shader","FS_SunsetSky.shader.meta","Materials/FS_SunsetSky.mat","Materials/FS_SunsetSky.mat.meta"};foreach(string file in protect)File.Copy("Assets/Afrer_Seconds/05.Model/Environment/1F/"+file,temp+"/before/"+Path.GetFileName(file),false);string bloom="Assets/Afrer_Seconds/06.Data/Rendering/1F/FL_FirstLightBloom.asset";File.Copy(bloom,temp+"/before/FL_FirstLightBloom.asset",false);
 var result=new{scene=s.path,props=details,terrains=terrain.Select(t=>new{t.name,path=AssetDatabase.GetAssetPath(t.terrainData),position=V(t.transform.position),size=V(t.terrainData.size),resolution=t.terrainData.heightmapResolution,t.basemapDistance,t.heightmapPixelError,material=AssetDatabase.GetAssetPath(t.materialTemplate),layers=t.terrainData.terrainLayers.Select(l=>new{path=AssetDatabase.GetAssetPath(l),diffuse=AssetDatabase.GetAssetPath(l.diffuseTexture),normal=AssetDatabase.GetAssetPath(l.normalMapTexture),tile=new[]{l.tileSize.x,l.tileSize.y},l.normalScale,l.smoothness,l.metallic,remap=new[]{l.diffuseRemapMax.x,l.diffuseRemapMax.y,l.diffuseRemapMax.z,l.diffuseRemapMax.w}})}).ToArray(),anchors=root.Cast<Transform>().Where(t=>t.name.StartsWith("Ending")||t.name=="FreedomVista").Select(t=>new{t.name,position=V(t.position)}).ToArray(),cameras=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).Select(c=>new{path=AnimationUtility.CalculateTransformPath(c.transform,null),c.farClipPlane}).ToArray()};File.WriteAllText(Out+"inventory.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{props=details.Length,terrains=terrain.Select(t=>t.name).ToArray(),backup=temp};}
}
